{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Emtricitabine, a closely related pyrimidine NRTI with very high assay transfer, has an absolute oral bioavailability of 93% in humans, directly supporting F≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Lamivudine, another closely related NRTI, shows absolute oral bioavailability of 87% from an oral solution in fasted patients, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Zalcitabine, a dideoxynucleoside analog, has absolute oral bioavailability of 88% in patients, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "The enantiomer of emtricitabine has absolute oral bioavailability of 58–97% in humans, well above the 20% threshold, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Theophylline, a small polar nucleobase-like drug, has systemic availability of 91.5%, supporting that this physicochemical class can be well absorbed orally.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is stavudine, a thymidine NRTI. The closest high-transfer analogues (emtricitabine, lamivudine, zalcitabine) all show absolute oral bioavailability well above 20% (66–97%), and the query's acid-stable unsaturated sugar and small neutral pyrimidine core are consistent with efficient oral absorption. Didanosine's lower F is mechanistically tied to acid lability and does not apply. Therefore F≥20% is strongly supported.",
  "evidence_gaps": [
    "No direct stavudine bioavailability record was supplied; prediction relies on high-transfer NRTI analogues.",
    "Didanosine low-F evidence was considered but not applied because its acid lability is not shared by the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

